
(()=>{const data={sculpt:{title:'胡桃木私邸',sub:'最接近你提供的棕皮、深木与粗织参考',copy:'巧克力棕皮沙发，搭配胡桃木低柜、叠层茶几和天然色织物。让深色集中在家具，墙面保留暖白，给小户型留下光线。',img:'/tour/legacy-assets/edce1500e2b56f51.jpg'},retro:{title:'橄榄沙龙',sub:'皮革、烟熏木与克制金属的现代主义组合',copy:'用橄榄绿皮革作为主角，小面积棕石与拉丝银产生对比。深色木作把色彩收拢，保留自然织物的温度。',img:'/tour/legacy-assets/485483608ed87fc4.jpg'},east:{title:'茶庭光影',sub:'木格栅、干邑棕与柔和纸感光线',copy:'把你喜欢的东方木质细节缩到局部柜门、边框和灯罩。低矮家具与细线条，让茶色木作在小空间里依然轻盈。',img:'/tour/legacy-assets/12660b7a5a3f37cb.jpg'},master:{title:'主卧 / 棉麻与木框',sub:'沿用原主卧转角窗与床位关系',copy:'保留明亮的转角采光，以木框床、亚麻软包、棉麻床品和低对比的地毯延续主方案。飘窗按实际台面深化。',img:'/tour/legacy-assets/6354da861e87f19a.jpg'},bath:{title:'卫生间 / 哑光石与暖木',sub:'依据原卫生间照片做材质替换',copy:'保留左侧淋浴、中间台盆和右侧窗位的照片关系。用低光泽瓷砖、深色台面与木色柜体衔接客卧。排水、柜体与防水仍须现场确认。',img:'/tour/legacy-assets/61fb8f9ee9bbd4dd.jpg'}};function show(key){if(['sculpt','retro','east'].includes(key))document.getElementById('daan-spaces').dataset.requestedStyle=key;const d=data[key]||data.sculpt;document.getElementById('render-image').src=d.img;document.getElementById('render-image').alt=d.title+'写实概念效果图';document.getElementById('render-title').textContent=d.title;document.getElementById('render-subtitle').textContent=d.sub;document.getElementById('render-copy').textContent=d.copy;document.querySelectorAll('[data-render]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.render===key)));document.dispatchEvent(new CustomEvent('tingjian:gallery',{detail:{key}}));}document.querySelectorAll('[data-render]').forEach(b=>b.addEventListener('click',()=>{const key=b.dataset.render;if(['sculpt','retro','east'].includes(key))document.querySelector('#daan-spaces [data-style="'+key+'"]').click();show(key);}));document.getElementById('daan-spaces').addEventListener('daan-style-change',e=>{if(e.detail.style!=='original')show(e.detail.style);});})();
